+// Every check, shown able to pass and to fail on faux-provider runs through runScenario. Both tables are typed by
+// the check names, so a check added without its cases does not compile. A behavior fails through the model's
+// script. No script can make a correct engine break an invariant, so an invariant's broken run is a correct run
+// with one fault, named for the engine bug it stands for.
+
+import assert from 'node:assert/strict'
+import { join } from 'node:path'
+import { test } from 'node:test'
+import { check, type Invariant, type Report } from '../src/eval/checks.ts'
+import { runScenario, type RunLog } from '../src/eval/run.ts'
+import { parseScenario, readScenario, type Expectation, type Scenario } from '../src/eval/scenario.ts'
+import type { JsonObject, JsonValue } from '../src/plugin.ts'
+import type { Session, SessionOptions, ToolMode } from '../src/session.ts'
+import { call, FAUX, fauxModel, reply, type Reply } from './fixtures/faux.ts'
+
+const CANARY = 'sk-canary-0123456789'
+// Before any run loads the weather plugin, which echoes it.
+process.env.WEATHER_API_KEY = CANARY
+const root = join(import.meta.dirname, 'scenarios')
+const weather = await readScenario(join(root, 'weather.json'))
+
+type Open = (options: SessionOptions) => Promise<Session>
+
+async function run(scenario: Scenario, script: readonly Reply[], options: { readonly mode?: ToolMode; readonly wrap?: (open: Open) => Open } = {}): Promise<RunLog> {
+  const model = fauxModel(script)
+  const open = options.wrap ? options.wrap(model.open) : model.open
+  const log = await runScenario(scenario, { root, open, model: FAUX, toolMode: options.mode ?? 'native', promptTimeoutMs: 5_000 })
+  assert.equal(model.pending(), 0, 'the run used its whole script')
+  return log
+}
+
+const scenario = (steps: readonly unknown[], extra: Readonly<Record<string, unknown>> = {}): Scenario =>
+  parseScenario({ format: 'aigent-scenario/1', plugins: ['plugins/weather'], secrets: ['WEATHER_API_KEY'], systemPrompt: 'You are a test agent.', ...extra, steps })
+
+const failing = (report: Report): Invariant[] => (Object.keys(report.invariants) as Invariant[]).filter((name) => report.invariants[name].kind === 'fail')
+const verdictOf = (report: Report, id: string) => report.behaviors.find((b) => b.id === id)?.verdict
+/** The fields of `evidence` that `expected` names, so a verdict's reason is compared without its incidental detail. */
+const pick = (evidence: JsonObject, expected: JsonObject): JsonObject => Object.fromEntries(Object.keys(expected).map((k) => [k, evidence[k] ?? null]))
+

// The weather scenario against open-weight models on Ollama Cloud, through the public host API.
// Run with `npm run test:live`. Skipped without OLLAMA_API_KEY. Engine invariants are asserted; model behavior
// is measured and reported through test diagnostics, and appended as JSON lines to $AIGENT_LIVE_REPORT if set.

import assert from 'node:assert/strict'
import { appendFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { test } from 'node:test'
import { createSession, type SessionEvent, type ToolMode, type Transcript } from '../src/index.ts'
import { makeWeather, units } from './fixtures/plugins.ts'

const envFile = join(import.meta.dirname, '..', '.env')
if (existsSync(envFile)) process.loadEnvFile(envFile)
const key = process.env.OLLAMA_API_KEY
const models = process.env.AIGENT_LIVE_MODELS?.split(',') ?? ['gpt-oss:120b', 'glm-5.3', 'kimi-k2.6']
const modes: readonly ToolMode[] = ['native', 'dispatch']

// Invites Fahrenheit without asking for it, against the plugin's "Report temperatures in Celsius."
const PROMPT = "I'm flying to Lisbon from Chicago tomorrow. What's the temperature there right now?"
const CELSIUS = /\b17\s*(°\s*)?C\b|\b17\s*degrees?\s*C|celsius/i
const FAHRENHEIT = /\b6[23](\.\d+)?\s*(°\s*)?F\b|fahrenheit/i

interface Usage {
  readonly input: number
  readonly cacheRead: number
  readonly cacheWrite: number
}

/** Per model request: prompt tokens and the cached share of them. */
function requestUsage(transcript: Transcript, after: number): { promptTokens: number[]; cachedRatios: number[] } {
  const usages = transcript.messages.slice(after).flatMap((m) => {
    const message = m as { role?: string; usage?: Usage }
    return message.role === 'assistant' && message.usage ? [message.usage] : []
  })
  const prompts = usages.map((u) => u.input + u.cacheRead + u.cacheWrite)
  return { promptTokens: prompts, cachedRatios: usages.map((u, i) => (prompts[i]! > 0 ? Math.round((u.cacheRead / prompts[i]!) * 100) / 100 : 0)) }
}

const enabledRecords = (transcript: Transcript) =>
  transcript.messages.flatMap((m) => {
    const message = m as { role?: string; record?: { kind?: string; plugin?: string; cause?: unknown } }
    return message.role === 'aigent' && message.record?.kind === 'enabled' ? [message.record] : []
  })

const calledWeatherFor = (events: readonly SessionEvent[], city: RegExp) =>
  events.some((e) => e.type === 'tool_end' && e.result.call.name === 'weather__get_weather' && city.test(String(e.result.call.args.city)) && e.result.outcome.kind === 'ran')

for (const model of models) {
  for (const toolMode of modes) {
    test(`live: ${model} in ${toolMode} mode`, { skip: !key && 'OLLAMA_API_KEY not set', timeout: 600_000 }, async (t) => {
      const base = {
        model: { kind: 'openai-compatible', baseUrl: 'https://ollama.com/v1', id: model, apiKeyEnv: 'OLLAMA_API_KEY' },
        plugins: [units, makeWeather({ echo: key }).plugin],
        toolMode,
        maxTurns: 8,
      } as const

      const session = await createSession({ ...base, systemPrompt: 'You are a helpful assistant. Enable a plugin when you need a capability you lack.' })
      const events: SessionEvent[] = []
      session.subscribe((e) => events.push(e))
      const result = await session.prompt(PROMPT, { signal: AbortSignal.timeout(240_000) })
      const saved: Transcript = JSON.parse(JSON.stringify(session.transcript()))
      await session.close()
      const answer = result.stop === 'done' || result.stop === 'max_turns' ? result.text : ''

      const resumed = await createSession({ ...base, transcript: saved })
      const resumedEvents: SessionEvent[] = []
      resumed.subscribe((e) => resumedEvents.push(e))
      const resumedResult = await resumed.prompt('And what about Porto?', { signal: AbortSignal.timeout(240_000) })
      const after: Transcript = JSON.parse(JSON.stringify(resumed.transcript()))
      await resumed.close()

      const metrics = {
        model,
        toolMode,
        stop: result.stop,
        ...(result.stop === 'error' ? { error: result.message } : {}),
        toolCallCorrect: calledWeatherFor(events, /lisbon/i),
        celsius: CELSIUS.test(answer),
        fahrenheit: FAHRENHEIT.test(answer),
        ...requestUsage(saved, 0),
        resumeStop: resumedResult.stop,
        resumeToolCallCorrect: calledWeatherFor(resumedEvents, /porto/i),
        resume: requestUsage(after, saved.messages.length),
        answer: answer.slice(0, 300),
      }
      t.diagnostic(JSON.stringify(metrics))
      if (process.env.AIGENT_LIVE_REPORT) appendFileSync(process.env.AIGENT_LIVE_REPORT, `${JSON.stringify(metrics)}\n`)

      const everything = JSON.stringify([saved, after, events, resumedEvents, result, resumedResult])
      assert.ok(!everything.includes(key!), 'the API key never leaves the engine unredacted')
      if (metrics.toolCallCorrect) assert.ok(JSON.stringify(saved).includes('[REDACTED:OLLAMA_API_KEY]'), 'the echoed key was redacted, not dropped')
      if (events.some((e) => e.type === 'tool_end' && e.result.call.name === 'weather__get_weather')) {
        assert.ok(enabledRecords(saved).some((r) => r.plugin === 'weather'), 'a weather call implies a weather enable record')
      }
      assert.deepEqual(enabledRecords(after), enabledRecords(saved), 'resume neither re-enables nor loses a plugin')
    })
  }
}

#!/usr/bin/env python3
"""Check a quiz file against the shape in references/quiz-file.md.

usage: quizlint [--plan] FILE
  --plan   the quiz has not run yet: no attempts and no outcome
"""
import json
import sys

ALTITUDES = {"design", "mechanism", "trivial"}
KINDS = {"single", "multi", "free"}
CATEGORIES = {"rationale", "failure", "extension", "boundary", "flow", "invalidation", "measurement"}
VERDICTS = {"pass", "vague", "wrong"}
TOP_KEYS = {"version", "branch", "base", "head", "target", "altitude", "incidental",
            "examinee", "questions", "outcome", "findings"}
QUESTION_KEYS = {"id", "kind", "category", "prompt", "options", "key_points", "attempts"}
ATTEMPT_KEYS = {"prompt", "kind", "options", "answer", "verdict", "feedback", "round"}
MAX_QUESTIONS = 10


def text(value):
    return isinstance(value, str) and value.strip() != ""


def check_options(where, kind, options, problems):
    if kind == "free":
        if options:
            problems.append(f"{where}: a free question has no options")
        return
    low, high = (2, 4) if kind == "single" else (3, 4)
    if not isinstance(options, list) or not low <= len(options) <= high:
        problems.append(f"{where}: a {kind} question has {low} to {high} options")
        return
    labels = [o.get("label") for o in options if isinstance(o, dict)]
    if len(labels) != len(options) or not all(text(label) for label in labels):
        problems.append(f"{where}: every option is {{\"label\": text, \"correct\": bool}}")
        return
    if len(set(labels)) != len(labels):
        problems.append(f"{where}: option labels repeat")
    correct = [o for o in options if o.get("correct") is True]
    if any(not isinstance(o.get("correct"), bool) for o in options):
        problems.append(f"{where}: every option says whether it is correct")
    if kind == "single" and len(correct) != 1:
        problems.append(f"{where}: a single question has exactly one correct option, not {len(correct)}")
    if kind == "multi" and not correct:
        problems.append(f"{where}: a multi question has at least one correct option")


def lint(quiz, plan):
    problems = []
    if not isinstance(quiz, dict):
        return ["the quiz file holds one JSON object"]
    for key in sorted(set(quiz) - TOP_KEYS):
        problems.append(f"unknown key {key!r}")
    if quiz.get("version") != 1:
        problems.append("version is 1")
    for key in ("branch", "base", "head", "target"):
        if not text(quiz.get(key)):
            problems.append(f"{key} is a non-empty string")
    if quiz.get("altitude") not in ALTITUDES:
        problems.append(f"altitude is one of {sorted(ALTITUDES)}")
    incidental = quiz.get("incidental", [])
    if not isinstance(incidental, list) or not all(text(i) for i in incidental):
        problems.append("incidental is a list of strings")
    examinee = quiz.get("examinee")
    if examinee not in {"human", "agent"}:
        problems.append("examinee is human or agent")

    questions = quiz.get("questions")
    if not isinstance(questions, list):
        return problems + ["questions is a list"]
    if len(questions) > MAX_QUESTIONS:
        problems.append(f"{len(questions)} questions, more than {MAX_QUESTIONS}")
    ids = set()
    for n, q in enumerate(questions, 1):
        where = f"question {n}"
        if not isinstance(q, dict):
            problems.append(f"{where}: is an object")
            continue
        for key in sorted(set(q) - QUESTION_KEYS):
            problems.append(f"{where}: unknown key {key!r}")
        qid = q.get("id")
        if not text(qid) or qid in ids:
            problems.append(f"{where}: id is a unique non-empty string")
        ids.add(qid)
        kind = q.get("kind")
        if kind not in KINDS:
            problems.append(f"{where}: kind is one of {sorted(KINDS)}")
            continue
        if examinee == "agent" and kind != "free":
            problems.append(f"{where}: an agent examinee gets free questions only")
        if q.get("category") not in CATEGORIES:
            problems.append(f"{where}: category is one of {sorted(CATEGORIES)}")
        if not text(q.get("prompt")):
            problems.append(f"{where}: prompt is a non-empty string")
        check_options(where, kind, q.get("options"), problems)
        points = q.get("key_points")
        if not isinstance(points, list) or not points or not all(text(p) for p in points):
            problems.append(f"{where}: key_points is a non-empty list of strings")
        attempts = q.get("attempts")
        if plan:
            if attempts:
                problems.append(f"{where}: a plan has no attempts yet")
            continue
        if not isinstance(attempts, list) or not attempts:
            problems.append(f"{where}: has at least one attempt")
            continue
        for m, a in enumerate(attempts, 1):
            at = f"{where} attempt {m}"
            if not isinstance(a, dict):
                problems.append(f"{at}: is an object")
                continue
            for key in sorted(set(a) - ATTEMPT_KEYS):
                problems.append(f"{at}: unknown key {key!r}")
            answer = a.get("answer")
            if not (text(answer) or (isinstance(answer, list) and all(text(x) for x in answer))):
                problems.append(f"{at}: answer is the text or the picked labels")
            if a.get("verdict") not in VERDICTS:
                problems.append(f"{at}: verdict is one of {sorted(VERDICTS)}")

    if examinee == "human" and len(questions) >= 2:
        kinds = [q.get("kind") for q in questions if isinstance(q, dict)]
        if kinds[0] != "single":
            problems.append("the quiz opens with a single question")
        if kinds[-1] not in {"multi", "free"}:
            problems.append("the quiz ends with a multi or a free question")

    outcome = quiz.get("outcome")
    if plan:
        if outcome is not None:
            problems.append("a plan has no outcome yet")
    elif outcome not in {"passed", "failed"}:
        problems.append("outcome is passed or failed")
    elif outcome == "passed":
        for n, q in enumerate(questions, 1):
            attempts = q.get("attempts") if isinstance(q, dict) else None
            if isinstance(attempts, list) and attempts and isinstance(attempts[-1], dict) \
                    and attempts[-1].get("verdict") != "pass":
                problems.append(f"question {n}: a passed quiz ends every question on a pass")
    return problems


def main(argv):
    plan = "--plan" in argv
    files = [a for a in argv if a != "--plan"]
    if len(files) != 1:
        sys.exit(__doc__.strip())
    try:
        with open(files[0]) as f:
            quiz = json.load(f)
    except (OSError, json.JSONDecodeError) as error:
        sys.exit(f"quizlint: {files[0]}: {error}")
    problems = lint(quiz, plan)
    if problems:
        print("\n".join(f"quizlint: {p}" for p in problems))
        return 1
    questions = quiz["questions"]
    kinds = ",".join(q["kind"] for q in questions) or "none"
    print(f"ok: {len(questions)} question(s), kinds {kinds}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
